+// syncHookFS wraps a vfs.FS and allows intercepting Sync calls on WAL (.log) files.
+type syncHookFS struct {
+	vfs.FS
+	onWALSync func() error
+}
+
+func (fs *syncHookFS) Create(name string, category vfs.DiskWriteCategory) (vfs.File, error) {
+	f, err := fs.FS.Create(name, category)
+	if err != nil {
+		return nil, err
+	}
+	if strings.HasSuffix(name, ".log") {
+		return &syncHookFile{File: f, fs: fs}, nil
+	}
+	return f, nil
+}
+
+func (fs *syncHookFS) ReuseForWrite(
+	oldname, newname string, category vfs.DiskWriteCategory,
+) (vfs.File, error) {
+	f, err := fs.FS.ReuseForWrite(oldname, newname, category)
+	if err != nil {
+		return nil, err
+	}
+	if strings.HasSuffix(newname, ".log") {
+		return &syncHookFile{File: f, fs: fs}, nil
+	}
+	return f, nil
+}
+
+type syncHookFile struct {
+	vfs.File
+	fs *syncHookFS
+}
+
+func (f *syncHookFile) Sync() error {
+	if f.fs.onWALSync != nil {
+		if err := f.fs.onWALSync(); err != nil {
+			return err
+		}
+	}
+	return f.File.Sync()
+}
+
+func (f *syncHookFile) SyncData() error {
+	if f.fs.onWALSync != nil {
+		if err := f.fs.onWALSync(); err != nil {
+			return err
+		}
+	}
+	return f.File.SyncData()
+}
