+func TestDurabilityCloseUnblocksWaitersAndPrecedence(t *testing.T) {
+	defer leaktest.AfterTest(t)()
+
+	d, err := Open("", &Options{FS: vfs.NewMem()})
+	require.NoError(t, err)
+
+	require.NoError(t, d.Set([]byte("k1"), []byte("v1"), Sync))
+	seq1, _ := d.DurableState()
+
+	wait1 := make(chan error, 1)
+	wait2 := make(chan error, 1)
+	go func() {
+		wait1 <- d.WaitForDurability(seq1 + 100)
+	}()
+	go func() {
+		wait2 <- d.WaitForDurabilityBatch([]base.SeqNum{seq1 + 100})
+	}()
+
+	require.Eventually(t, func() bool {
+		return d.DurabilityStats().PendingWaiters == 2
+	}, 2*time.Second, time.Millisecond)
+
+	require.NoError(t, d.Close())
+
+	require.Error(t, <-wait1)
+	require.Error(t, <-wait2)
+	require.Equal(t, int64(0), d.DurabilityStats().PendingWaiters)
+
+	// Close error takes precedence over cancelled context.
+	cancelledCtx, cancel := context.WithCancel(context.Background())
+	cancel()
+	err = d.WaitForDurabilityContext(cancelledCtx, seq1)
+	require.ErrorIs(t, err, ErrClosed)
+	err = d.WaitForDurabilityBatchContext(cancelledCtx, []base.SeqNum{seq1})
+	require.ErrorIs(t, err, ErrClosed)
+	err = d.WaitForJobDurabilityContext(cancelledCtx, 1)
+	require.ErrorIs(t, err, ErrClosed)
+}
